          rich("W_{y}^{δ}(p) = a_{ϑ}^{δ}a_{y}^{ϑ}/[p^{2}(p^{2}+a_{ϑ}^{ϑ})] = " + nf(gAy, 0) + "/[p^{2}(p^{2}−" + nf(AT, 2) + ")]", W / 2, yy + gap, C.new, { size: fs - (narrow ? 1.5 : 0), align: "center" });
