    wy: sub(mi("ω"), mi("y")), fy: sub(mi("f"), mi("y")), Py: sub(mi("P"), mi("y")),
    rate: "<mrow>" + mi("Δ") + sub(dotted("ϑ"), mi("ККП")) + "</mrow>",
    ang: "<mrow>" + mi("Δ") + sub(mi("ϑ"), mi("ККП")) + "</mrow>",
    acc: "<mrow>" + mi("Δ") + sub(ddotted("ϑ"), mi("y")) + "</mrow>",
