  const mi = t => "<mi>" + t + "</mi>", mn = t => "<mn>" + t + "</mn>", mo = t => (t === "(" || t === ")" ? '<mo lspace="0" rspace="0" stretchy="false">' + t + "</mo>" : "<mo>" + t + "</mo>");
