    kd: sub(mi("k"), rm("д")), kth: sub(mi("k"), mi("ϑ")), krp: sub(mi("k"), rm("рп")), dT: sub(mi("δ"), rm("т")), upos: sub(mi("u"), rm("пос")), kpos: sub(mi("k"), rm("пос")),
    Ain: sub(mi("A"), rm("вх")), Aout: sub(mi("A"), rm("вых")), w0: sub(mi("ω"), mn("0")),
