      const sz0 = (o.size || 13) * kk, wt = o.weight || 600, halo = o.halo === undefined ? 4 : o.halo;
      const setf = s => { ctx.font = wt + " " + s.toFixed(1) + "px " + (o.mono ? C.mono : C.font); };
      const runs = parseRich(txt);
