  const gp = (v, d) => {
    const s = nf(v, d), m = /^(−?)(\d+)(,\d+)?$/.exec(s);
    return m ? m[1] + m[2].replace(/\B(?=(\d{3})+(?!\d))/g, " ") + (m[3] || "") : s;
  };
  const SUPD = "⁰¹²³⁴⁵⁶⁷⁸⁹";
