  const S = s => String(s).replace(/\{(\w+)\}/g, (m, k) => SYM[k] ? "<math>" + SYM[k] + "</math>" : m);

  /* ---------- ชุดวาดร่วม ---------- */
  /* ข้อความบนภาพรองรับตัวห้อย _{…} ตัวยก ^{…} จุดบน '{…} และสองจุดบน ''{…} */
