      const ps = parts(String(txt));
      const setf = s => { ctx.font = wt + " " + s.toFixed(1) + "px " + fam; };
      const ms = ps.map(p => { setf(p.k === "_" || p.k === "^" ? small : sz); return ctx.measureText(p.t).width; });
      const tw = ms.reduce((a, b) => a + b, 0);
      const al = o.align || "left";
      let left = al === "left" ? x : al === "right" ? x - tw : x - tw / 2;
      left = Math.max(3, Math.min(W - 3 - tw, left));
      y = Math.max(8, Math.min(H - 8, y));
