          { k: "รากจริงที่ข้ามไปฝั่งขวา", v: rootTxt(rt[0]) + " с⁻¹ (ค่าคงที่เวลา ≈ " + nf(1 / rt[0][0], 1) + " с)" },
          { k: "อีกสองราก (ยังอยู่ฝั่งซ้าย)", v: rootTxt(rt[1]) }
