        T.line([[kmin8, 0], [kmin8, YMAX]], C.ink3, 1.7, [6, 5], T.vis(3, 3));
        T.line([[km, 0], [km, YMAX]], C.ref, 2.6, [], T.vis(1));
        T.lab("{K} = " + nf(km, 2), km, 15.7, 7, 0, C.ref, {}, T.vis(1, 2));
        T.lab("a₃ > 0 · เสถียรฝั่งนี้", km, 11.8, 8, 0, C.ok, { size: 12 }, T.vis(1, 2));
        T.lab("เส้นประ: aϑϑ = −0,80 → " + nf(kmin8, 2), kmin8, 12.6, 8, 0, C.ink2, { size: 12 }, T.vis(3, 3));
